window.POETRY_REGISTER("v5-strict-6-11-0-a2ca908e5f6d.js",{"poems":[[53192,2],[53858,2],[56718,2],[150898,7],[155965,7],[251182,7],[266349,7],[266353,7],[272147,7],[293535,7],[312501,7],[314451,7],[318000,7],[343205,9],[376600,10],[416974,8],[436938,8],[524933,8],[538833,8],[548086,8],[570576,8],[589675,8],[595847,8],[613264,8],[652443,5],[654999,5]],"pairs":[["据张忱石考证","彦修当为文宗至僖宗时人",0],["录诗的原则是","尽可能地保持王诗的原貌",1],["后文正果大用","诏赐所居为谢元卿秉钧里",2],["向千圣顶𩕳上","有时露出佛祖莫穷底机关",3],["遥增击而栩栩","亦何异一丘一壑之相羊耶",4],["既轻举以远睐","众流靡靡兮汩独与吾相遭",5],["漭无极兮天游","不知干之为马兮坤之为牛",6],["猗若人兮深衣","万锺不为泰兮一箪而遯肥",7],["故淳熙之士夫","亦不敢一日而忘可将之奇",8],["从教戴天履地","击壤鼓腹兮不知天地之宽",9],["孤洁不易保兮","故多以皎皎而受人之昏昏",10],["山中春兮可乐","王孙不来兮謇谁留兮他山",11],["直饶火急翻身","四大海水早已倾在汝耳里",12],["闻说名泉奇观","倒泻银河千丈玉乳溅飞花",13],["满笔淋漓醉墨","应有山灵夜护林壑动龙蛇",13],["此时命不自保","嗟彼吴盐蜀锦那得利吾财",14],["繄千秋兮万年","子子孙孙兮期永保而无斁",15],["睨首阳之高洁","吾不知其竹之犹夷齐者耶",16],["君不行兮何迟","吾将期汝朱明耀真之洞天",17],["瑶台高兮缥缈","中有人兮丹颜绿发而衣缟",18],["有时察举高宦","无事可以啜菽饮水乐儒素",19],["岂其与道逍遥","故能坚齿发而寿岁月也耶",20],["泉之流兮汤汤","我之怀矣与泉偕逝而无忘",21],["泉之鸣兮泠泠","我之怀矣与泉偕滴而无声",21],["超氛埃兮淑丽","贞臣匪放兮省疚瘵之希微",22],["瑶台高兮缥缈","中有人兮丹颜绿发而衣缟",23],["其一曰富锡尔","将军命之携印以出归帝里",24],["好坐剑阁峨眉","凛冽凄清古雪吹空寒瑟瑟",25],["好踞泰山日观","悠扬迢递罡风响入秋冥冥",25]]});
